const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    terminal: false
});

rl.on('line', (line) => {
    const [n, m, a, b] = line.split(' ').map(Number);

    // Option 1: buy only single tickets
    const cost1 = n * a;

    // Option 2: buy only m-ride tickets (enough to cover n rides)
    const mTickets = Math.ceil(n / m);
    const cost2 = mTickets * b;

    // Option 3: mix of m-ride tickets and single tickets
    // Try all possible numbers of m-ride tickets from 0 to Math.floor(n/m)
    let minCost = Infinity;
    const maxMTickets = Math.floor(n / m);
    for (let i = 0; i <= maxMTickets; i++) {
        const remaining = n - i * m;
        const cost = i * b + remaining * a;
        if (cost < minCost) {
            minCost = cost;
        }
    }

    // Also consider buying one more m-ride ticket than needed (if it's cheaper)
    // Actually, the above loop covers up to floor(n/m). We should also check if buying 
    // ceil(n/m) m-tickets is better, but that's covered by cost2.
    // Let's just take the minimum of all options

    const result = Math.min(cost1, cost2, minCost);
    console.log(result);
});
