    input: process.stdin,
    terminal: false
});

let line = '';
rl.on('line', (input) => {
    const parts = input.trim().split(' ').map(Number);
    const n = parts[0];
    const m = parts[1];
    const a = parts[2];
    const b = parts[3];

    // Option 1: All single tickets
    const costAllSingle = n * a;

    // Option 2: All m-ride tickets (buy enough to cover n rides)
    const numMTickets = Math.ceil(n / m);
    const costAllM = numMTickets * b;

    // Option 3: Mix of m-ride tickets and single tickets
    // Try all possible numbers of m-ride tickets from 0 to floor(n/m)
    let minCost = Infinity;
    for (let i = 0; i <= Math.floor(n / m); i++) {
        const ridesCovered = i * m;
        const remainingRides = n - ridesCovered;
        const cost = i * b + remainingRides * a;
        if (cost < minCost) {
            minCost = cost;
        }
    }

    // Also consider buying one extra m-ride ticket if it's cheaper than single tickets for the remainder
    // This is already covered by the loop above, but let's also check the case where we buy 
    // floor(n/m) m-tickets and then decide between single tickets or one more m-ticket
    const fullMTickets = Math.floor(n / m);
    const remainder = n % m;

    // Cost with full m-tickets + single tickets for remainder
    const costFullPlusSingle = fullMTickets * b + remainder * a;
    if (costFullPlusSingle < minCost) {
        minCost = costFullPlusSingle;
    }

    // Cost with full m-tickets + one more m-ticket (if remainder > 0)
    if (remainder > 0) {
        const costFullPlusExtraM = (fullMTickets + 1) * b;
        if (costFullPlusExtraM < minCost) {
            minCost = costFullPlusExtraM;
        }
    }

    // The minimum of all options
    const result = Math.min(costAllSingle, costAllM, minCost);

    console.log(result);
});
