    const parts = line.trim().split(/\s+/).map(Number);
    const [n, m, a, b] = parts;

    let minCost = Infinity;

    // Option 1: Buy all single tickets
    let cost1 = n * a;
    minCost = Math.min(minCost, cost1);

    // Option 2: Buy some m-ride tickets and the rest single tickets
    // We can buy k m-ride tickets where k ranges from 0 to ceil(n/m)
    // But we don't need more than enough to cover n rides
    const maxMTickets = Math.ceil(n / m);
    for (let k = 0; k <= maxMTickets; k++) {
        const ridesCovered = k * m;
        const remainingRides = Math.max(0, n - ridesCovered);
        const cost = k * b + remainingRides * a;
        minCost = Math.min(minCost, cost);
    }

    // Also consider buying more m-ride tickets than strictly needed (in case b is very cheap)
    // Actually, the loop above covers k up to ceil(n/m), which might include extra rides.
    // But let's also check if buying exactly floor(n/m) or ceil(n/m) is optimal.
    // The loop already handles all k from 0 to ceil(n/m), so it should be fine.

    console.log(minCost);
});
